/**
 * Copies the properties a key map names onto a new object under their shortened
 * wire names, skipping anything the map does not mention.
 *
 * Every encoder does this, at every level of its payload. Written out inline it
 * indexes a precisely-typed result with a `string`, which needs an implicit
 * `any` at each assignment - twenty-nine of them across the four encoders under
 * `strict`. Centralising it puts the one unavoidable cast in a single place:
 * callers name the encoded type, and the key maps' `satisfies` clauses are what
 * prove the mapping covers every field of the source.
 */
export function remapKeys(source, keyMap) {
    const encoded = {};
    // `for...in` rather than `Object.keys`, matching what the encoders did before:
    // the sources are plain payload objects, and metric classes keep their getters
    // on the prototype where neither form can see them - those are copied across
    // explicitly by `CustomMetricsEncoder`.
    for (const key in source) {
        // `hasOwn` rather than a truthiness check: `keyMap["toString"]` is the
        // inherited function, and an attribute named that way would land under a
        // key spelt from its source code.
        if (!Object.hasOwn(keyMap, key)) {
            continue;
        }
        const mapped = keyMap[key];
        if (mapped) {
            encoded[mapped] = source[key];
        }
    }
    return encoded;
}
